ValidationRule.errorConditionFormula:
AND ( RecordTypeId = "01290000001UPUR", /*Sales Offers Request*/ NOT ( $User.UserRoleId = $Label.QF_Support_QIC_Member), /*QF-Support-Agency Support-QAC*/ NOT ( $Profile.Name = "System Administrator"), /*System Administrator*/ NOT ( $Profile.Name = "Qantas System Administrator"), NOT ( $Profile.Name = "Qantas System Admin - Freight"), NOT ( $Profile.Name = "Qantas System Admin - QCC"), NOT ( $Profile.Name = "Qantas System Admin - SND"), OR ( ISPICKVAL ( Type , "Campaign" ), AND(ISPICKVAL ( Type , "Adhoc" ),NOT(ISPICKVAL(Sub_Type__c,"QC Member Gifting"))) ),
OR ( ISBLANK( Campaign_Start_Date__c ), Campaign_Start_Date__c < TODAY(), DAY( Campaign_Start_Date__c ) <> 1
)
)
